const SORT_OPTIONS=new Map([["position","手动顺序"],["updated_desc","最近更新"],["updated_asc","最早更新"],["created_desc","最新创建"],["created_asc","最早创建"],["due_desc","最晚截止"],["due_asc","最早截止"]]),SORT_STORAGE_KEY="kanban-column-sorts";
